package com.littlemakers.village.nativeapp;
public final class StageProjectionTest {
 public static void main(String[]args){int count=0;for(int w:new int[]{320,360,480,1080,1200})for(int h:new int[]{180,360,520,800,1920})for(float scene:new float[]{250,280,320,520,640,840,1000}){float xPixelsPerUnit=w/640f;float yPixelsPerUnit=h/scene*StageProjection.modelYScale(w,h,scene);if(Math.abs(xPixelsPerUnit-yPixelsPerUnit)>.00001f)throw new AssertionError("Flattened model "+w+"x"+h+" / "+scene);float fit=StageProjection.modelFit(w,h,scene);if(fit<=0||fit>1||Math.abs(xPixelsPerUnit*fit-yPixelsPerUnit*fit)>.00001f)throw new AssertionError("Invalid model fit");if(scene==520&&185*h/scene-56*w/640f*fit<0)throw new AssertionError("Book clipped by viewport");count++;}for(int[]bad:new int[][]{{0,1},{1,0},{-1,2}}){try{StageProjection.modelYScale(bad[0],bad[1],840);throw new AssertionError("invalid viewport");}catch(IllegalArgumentException expected){}}System.out.println("PASS "+count+" viewport combinations preserve uniform model proportions, bounded model fit and uncropped school book framing.");}
}
